local voice = meldritch.subpatch("gated_oscillator")
local oscillator = voice:module("oscillator", "sine", { frequency = 0.0 })
local envelope = voice:module("envelope", "envelope", { attack = 0.5, release = 0.25 })
local level = voice:module("level", "gain", { gain = 0.25 })
local closed = voice:module("closed", "constant", { value = 0.0 })
voice:connect(oscillator.out, level.input)
voice:connect(envelope.out, level.mod)
voice:normalize(closed.out, envelope.gate)
voice:input("pitch", oscillator.fm_hz)
voice:input("gate", envelope.gate)
voice:output("audio", level.out)

local graph = meldritch.graph()
local left_pitch = graph:module("left_pitch", "constant", { value = 12000.0 })
local right_pitch = graph:module("right_pitch", "constant", { value = 6000.0 })
local left_gate = graph:module("left_gate", "constant", { value = 1.0 })
local right_gate = graph:module("right_gate", "constant", { value = 0.0 })
local left = graph:instance("left", voice)
local right = graph:instance("right", voice)
local mix = graph:module("mix", "mix")
local output = graph:module("output", "output")
graph:connect(left_pitch.out, left.pitch)
graph:connect(right_pitch.out, right.pitch)
graph:connect(left_gate.out, left.gate)
graph:connect(right_gate.out, right.gate)
graph:connect(left.audio, mix.left)
graph:connect(right.audio, mix.right)
graph:connect(mix.out, output.input)
return graph
